'use strict';

/**
 * Cheat sheet — the study notes, split by handbook chapter.
 *
 * Covers: the cheat sheet shipped with the app, the "Cheat" tab, the chapter
 * chooser, the chapter chips, the note button on every category row, the blocks
 * (tables, nested lists, quotes) rendering, and the back path from a chapter
 * back to the chooser.
 *
 * The notes themselves are generated by tools/build-cheatsheet.js from
 * Cheat_Sheet.md, so these tests talk about structure (chapter ids, section
 * titles, table shapes) rather than about any particular fact.
 */

const { launch } = require('../harness');

const POOL = 716;
const CHAPTERS = ['values_principles', 'what_is_uk', 'history', 'modern_society', 'government_law'];

module.exports = {
  name: 'Cheat sheet',
  async run(suite, ctx) {
    const browser = await launch();
    try {
      const page = await browser.newPage();
      await page.goto(ctx.base + '/');
      await page.ready(POOL);

      const tab = '.tab[data-tab="cheat"]';
      const rows = "#main .cat-row[data-action='cheat-open'][data-ch]";

      await suite.group('The cheat sheet ships with the app', async () => {
        suite.eq('five chapters were loaded', await page.eval('return DATA.cheat.chapters.length'), 5);
        suite.eq(
          'the chapters follow the pool order',
          await page.eval('return DATA.cheat.chapters.map(function (c) { return c.id; }).join(",")'),
          CHAPTERS.join(',')
        );
        suite.eq(
          'every chapter carries its pool name and a chip label',
          await page.eval(
            'return DATA.cheat.chapters.every(function (c) { return !!c.name && c.name.length > 3 && !!c.chip; })'
          ),
          true
        );
        suite.eq(
          'every chapter has at least one section',
          await page.eval('return DATA.cheat.chapters.every(function (c) { return c.sections.length > 0; })'),
          true
        );
        suite.eq(
          'every section has at least one block',
          await page.eval(
            'return DATA.cheat.chapters.every(function (c) { return c.sections.every(function (s) { return s.blocks.length > 0; }); })'
          ),
          true
        );
        suite.eq(
          'no raw markdown survives into the blocks',
          await page.eval(
            'var bad = 0; DATA.cheat.chapters.forEach(function (c) { c.sections.forEach(function (s) { s.blocks.forEach(function (b) { if (b.t === "table") { b.rows.forEach(function (r) { r.forEach(function (x) { if (/\\*\\*/.test(x)) bad++; }); }); } else if (b.t === "ul") { b.items.forEach(function (i) { if (/\\*\\*/.test(i.html)) bad++; }); } else if (b.html && /\\*\\*/.test(b.html)) bad++; }); }); }); return bad === 0;'
          ),
          true
        );
      });

      await suite.group('The Cheat tab opens the chooser', async () => {
        suite.check('the tab bar has a cheat tab', await page.exists(tab));
        suite.check('labelled Cheat', (await page.text(tab)).indexOf('Cheat') >= 0);

        await page.click(tab);
        await page.waitFor("ui.tab === 'cheat'");
        suite.eq('the header names the sheet', await page.text('#headerSubtitle'), 'Cheat sheet');
        suite.eq(
          'the back button is hidden at the top level',
          await page.eval('return document.getElementById("backBtn").hidden'),
          true
        );
        suite.eq('no chapter is selected yet', await page.eval('return ui.cheat && ui.cheat.ch'), null);
      });

      await suite.group('The chooser lists every chapter', async () => {
        suite.eq('one row per chapter', await page.count(rows), 5);
        const text = await page.text('#main');
        for (const c of CHAPTERS) {
          const name = await page.eval(
            `return DATA.cheat.chapters.filter(function (x) { return x.id === '${c}'; })[0].name;`
          );
          suite.check(`chapter listed: ${c}`, text.indexOf(name) >= 0);
        }
        suite.check('each row says how many sections it has', /\d+ sections?/.test(text));
      });

      await suite.group('A chapter renders its notes', async () => {
        await page.click(`[data-action='cheat-open'][data-ch='history']`);
        await page.waitFor("ui.tab === 'cheat' && ui.cheat.ch === 'history'");

        const sections = await page.eval(
          "return DATA.cheat.chapters.filter(function (c) { return c.id === 'history'; })[0].sections.map(function (s) { return s.title; });"
        );
        const headings = await page.eval(
          "return Array.prototype.map.call(document.querySelectorAll('#main h2.section'), function (n) { return n.innerText.trim().toLowerCase(); });"
        );
        // innerText reflects the uppercase CSS, so compare case-insensitively.
        for (const s of sections) suite.check(`section rendered: ${s}`, headings.indexOf(s.toLowerCase()) >= 0);
        suite.eq('every section of the chapter is on the page', headings.length, sections.length);

        suite.check('the chapter has tables', (await page.count('.cheat-table')) >= 1);
        suite.eq(
          'the table matches the data',
          await page.eval(
            "var c = DATA.cheat.chapters.filter(function (x) { return x.id === 'history'; })[0]; var t = c.sections.filter(function (s) { return s.title === 'History Dates'; })[0].blocks.filter(function (b) { return b.t === 'table'; })[0]; var dom = document.querySelectorAll('.cheat-table')[0]; return dom.rows.length === t.rows.length + 1 && dom.rows[0].cells.length === t.head.length;"
          ),
          true
        );
      });

      await suite.group('Nested lists and quotes keep their shape', async () => {
        await page.click("[data-action='cheat-open'][data-ch='what_is_uk']");
        await page.waitFor("ui.cheat.ch === 'what_is_uk'");
        suite.eq(
          'the currency sub-list is nested',
          await page.eval("return document.querySelectorAll('.cheat-list .cheat-list li').length >= 2;"),
          true
        );

        await page.click("[data-action='cheat-open'][data-ch='values_principles']");
        await page.waitFor("ui.cheat.ch === 'values_principles'");
        suite.check('the anthem is rendered as a quote', await page.exists('blockquote'));
        suite.check('and keeps its lines', (await page.text('blockquote')).indexOf('God save our gracious King') >= 0);
      });

      await suite.group('The chapter chips switch chapters', async () => {
        await page.click(".chip[data-action='cheat-open'][data-ch='government_law']");
        await page.waitFor("ui.cheat.ch === 'government_law'");
        const name = await page.eval(
          "return DATA.cheat.chapters.filter(function (c) { return c.id === 'government_law'; })[0].name;"
        );
        suite.check('the notes name the new chapter', (await page.text('#main')).indexOf(name) >= 0);
        suite.eq(
          'the active chip follows',
          await page.eval("return document.querySelector('.chip.is-on').dataset.ch === 'government_law';"),
          true
        );

        await page.click(".chip[data-action='cheat-open']:not([data-ch])");
        await page.waitFor('ui.cheat.ch === null');
        suite.eq('"All chapters" returns to the chooser', await page.count(rows), 5);
      });

      await suite.group('A note button on a category row opens that chapter', async () => {
        await page.click('.tab[data-tab="practice"]');
        await page.waitFor("ui.tab === 'practice'");

        const buttons = await page.count('.cat-line [data-action="cheat-open"][data-ch]');
        suite.eq('every category row has a note button', buttons, 5);
        suite.eq(
          'the note buttons point at their own category',
          await page.eval(
            "var ids = Array.prototype.map.call(document.querySelectorAll('.cat-line [data-action=\"cheat-open\"][data-ch]'), function (b) { return b.dataset.ch; }); return ids.join(',') === DATA.cheat.chapters.map(function (c) { return c.id; }).join(',');"
          ),
          true
        );

        await page.click(".cat-line [data-action='cheat-open'][data-ch='modern_society']");
        await page.waitFor("ui.tab === 'cheat' && ui.cheat.ch === 'modern_society'");
        suite.eq('the row button opens that chapter in the cheat tab', await page.eval('return ui.tab'), 'cheat');
      });

      await suite.group('Back walks out of the chapter', async () => {
        suite.eq(
          'the back button appears once a chapter is open',
          await page.eval('return !document.getElementById("backBtn").hidden'),
          true
        );
        await page.click('#backBtn');
        await page.waitFor('ui.cheat.ch === null');
        suite.eq('chapter -> chooser', await page.eval('return ui.tab'), 'cheat');
        suite.eq(
          'and the chooser is the top level again',
          await page.eval('return document.getElementById("backBtn").hidden'),
          true
        );
      });

      await suite.group('Every chapter renders cleanly', async () => {
        for (const c of CHAPTERS) {
          await page.eval(`ui.cheat = { ch: '${c}' }; ui.screen = 'home'; setTab('cheat'); render();`);
          const sections = await page.eval(
            `return DATA.cheat.chapters.filter(function (x) { return x.id === '${c}'; })[0].sections.length;`
          );
          suite.eq(`${c}: all sections rendered`, await page.count('#main h2.section'), sections);
          suite.check(`${c}: has something to read`, (await page.count('#main .card')) >= 1);
        }
      });

      await suite.group('No client-side errors', async () => {
        const problems = page.problems();
        suite.check('no console errors or failed requests', problems.length === 0, problems.join(' | '));
      });

      await page.close();
    } finally {
      await browser.close();
    }
  },
};
